-- PT122-S1-Q20. Approved 2026-10-01.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT122-S1-Q20$batch02$ AND q.stimulus=$batch02$The people most likely to watch a televised debate between political candidates are the most committed members of the electorate and thus the most likely to have already made up their minds about whom to support. Furthermore, following a debate, uncommitted viewers are generally undecided about who won the debate. Hence, winning a televised debate does little to bolster one’s chances of winning an election.$batch02$ AND q.prompt=$batch02$The reasoning in the argument is most vulnerable to criticism because the argument fails to consider the possibility that$batch02$ AND q.correct_choice=$batch02$B$batch02$) THEN RAISE EXCEPTION 'Question changed: PT122-S1-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch02$PT122-S1-Q20$batch02$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S1-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT122-S1-Q20$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Winning a televised debate does little to help a candidate win the election.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Most viewers already know whom they support, and the uncommitted viewers usually cannot say who won.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Every piece of evidence is about people who *watch* the debate. But a debate can reach voters who never saw it. The next day's headlines say "Smith wins debate," clips circulate, and friends talk about it. Undecided voters who skipped the debate could be swayed by that coverage. The argument checks only the direct audience and concludes about the debate's whole effect.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for a way winning could help through people other than the viewers the author examined.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT122-S1-Q20$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$If an exciting debate raises turnout, that boosts voting generally. It does not say more of those voters choose the debate's winner, so it does not show that winning helps.$batch02$), ($batch02$B$batch02$, $batch02$Non-watchers can learn who won through news reports. If those reports shape their votes, winning a debate can matter a lot even though the viewers themselves are committed or confused. This names exactly the group the evidence left out.$batch02$), ($batch02$C$batch02$, $batch02$Disagreement over who won fits the author's point that uncommitted viewers are unsure of the winner. If anything, it makes "winning" seem less able to move votes.$batch02$), ($batch02$D$batch02$, $batch02$Unpredictable effects do not favor the winner. To weaken the conclusion, we need a reason that *winning* helps, not just a reason that something unpredictable happens.$batch02$), ($batch02$E$batch02$, $batch02$Committed voters sticking with their candidate after a loss supports the claim that the debate result does little to change votes.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT122-S1-Q20$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
